    environment.update(CODEX_PROJECT_CACHE_ROOT=CACHE,GOEXPERIMENT='simd',GOMAXPROCS='1',GOGC='100',GOAV1_PUBLIC_FULLCLIP_SAMPLES='1',GOAV1_BENCH_CORPUS_DIR=str(CORPUS))
